<script>(()=>{const modal=document.getElementById('price-list-modal'),open=()=>{modal?.classList.remove('hidden');modal?.classList.add('flex')},close=()=>{modal?.classList.add('hidden');modal?.classList.remove('flex')};document.querySelectorAll('[data-open-price-list]').forEach(b=>b.onclick=open);document.querySelectorAll('[data-close-price-list]').forEach(b=>b.onclick=close);if(@json((bool)$editing||request()->boolean('create')))open();const selected=new Set(@json(array_values(array_map('strval',$selectedIds)))),hidden=document.getElementById('selected-hidden'),count=document.getElementById('selected-count'),render=()=>{if(count)count.textContent=selected.size;if(hidden)hidden.innerHTML=[...selected].map(id=>`<input type="hidden" name="selected_ids[]" value="${id}">`).join('')};document.querySelectorAll('.product-checkbox').forEach(cb=>cb.onchange=()=>{cb.checked?selected.add(cb.value):selected.delete(cb.value);render()});document.getElementById('clear-selection')?.addEventListener('click',()=>{selected.clear();document.querySelectorAll('.product-checkbox').forEach(x=>x.checked=false);render()});document.getElementById('product-filter')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.product-row').forEach(r=>r.classList.toggle('hidden',q&&!r.dataset.search.includes(q)))});render();
const em=document.getElementById('email-modal'),ef=document.getElementById('email-send-form'),pdf=document.getElementById('email-pdf'),note=document.getElementById('email-pdf-note');document.querySelectorAll('[data-email-open]').forEach(b=>b.onclick=()=>{const card=b.closest('.export-card'),available=card?.querySelector('a[href*="/pdf/download"]')!==null;ef.action=`{{ url('/apps/muasamcong/price-list') }}/${b.dataset.emailOpen}/email`;pdf.disabled=!available;pdf.checked=available;if(note)note.textContent=available?'PDF đã sẵn sàng, có thể gửi cùng Excel.':'PDF chưa sẵn sàng; hãy Convert PDF trước.';em.classList.remove('hidden');em.classList.add('flex')});document.querySelectorAll('[data-email-close]').forEach(b=>b.onclick=()=>{em.classList.add('hidden');em.classList.remove('flex')});
document.querySelectorAll('.share-export').forEach(b=>b.onclick=async()=>{const recipient=prompt('Người nhận / đơn vị nhận link (để lưu lịch sử):','')??'';try{const body=new URLSearchParams({recipient});const r=await fetch(b.dataset.share,{method:'POST',headers:{Accept:'application/json','X-CSRF-TOKEN':@json(csrf_token()),'Content-Type':'application/x-www-form-urlencoded'},body});if(!r.ok)throw Error('Không thể tạo link chia sẻ.');const d=await r.json();if(navigator.share)await navigator.share({title:'Bảng Giá',url:d.url});else{await navigator.clipboard.writeText(d.url);alert('Đã sao chép link chia sẻ.');}setTimeout(()=>location.reload(),500)}catch(e){if(e.name!=='AbortError')alert(e.message)}});
const cards=[...document.querySelectorAll('.export-card')];if(cards.some(c=>c.dataset.pending==='1'||c.textContent.includes('Queue đang chuyển'))){const t=setInterval(async()=>{for(const c of cards){try{const r=await fetch(c.dataset.statusUrl,{headers:{Accept:'application/json'}});if(r.ok){const d=await r.json();if(d.status==='completed'||d.status==='failed'||d.pdf_status==='completed'||d.pdf_status==='failed'){clearInterval(t);location.reload();return}}}catch(e){}}},2500);setTimeout(()=>clearInterval(t),180000)}@if($queueExportId)document.getElementById('queue-continue')?.addEventListener('click',()=>document.getElementById('queue-modal')?.remove());@endif})();</script>
